return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Turkish','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:36+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'tr_TR','plural-forms'=>'nplurals=2; plural=n != 1;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" kaydedildi.','"%1$s" created. %2$d template updated.'=>'"%1$s" oluşturuldu. %2$d şablon güncellendi.' . "\0" . '"%1$s" oluşturuldu. %2$d şablon güncellendi.','"%s" created.'=>'"%s" oluşturuldu.','%d language not yet linked'=>'%d dil henüz bağlantılı değil' . "\0" . '%d dil henüz bağlantılı değil','%d link updated.'=>'%d bağlantı güncellendi.' . "\0" . '%d bağlantı güncellendi.','%d locale pack installed.'=>'%d yerel paket yüklü.' . "\0" . '%d yerel paket yüklü.','%d navigation reference updated.'=>'%d gezinme referansı güncellendi.' . "\0" . '%d gezinme referansı güncellendi.','%d part reference updated.'=>'%d parça referansı güncellendi.' . "\0" . '%d parça referansı güncellendi.','%s Archive'=>'%s Arşivi','(avg %.1f hits/block)'=>'(ortalama %.1f erişim/blok)','(avg %.1f hits/entry)'=>'(ortalama %.1f vuruş/entry)','(disabled)'=>'(devre dışı)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} değiştirilmesi gereken bağlantı yok — araştırmak için tekrar tara)','.txt file(s) in the directory'=>'.txt dosyası(ları) dizinde','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d yerelleştirilmiş şablon(lar) &#8220;%2$s&#8221; temasından veritabanında korunuyor, ancak şu anda etkin değil. Bu temayı yeniden etkinleştirirseniz, tekrar aktif hale gelirler. Çevirilerinizi yeni temaya taşımak için, <strong>Ayarlar → Lingua Forge → Yönlendirici → FSE iskeleti</strong> aracılığıyla yeniden oluşturun.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> otomatik düzeltilebilir bağlantı','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> manuel inceleme gerektiren bağlantı','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> eski yol(lar)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> şablon sorunu(ları)','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Sadece derlenmiş .mo dosyalarını kabul eder. Dosya adı {textdomain}-{locale}.mo kalıbını takip etmelidir. Aynı isimdeki bir dosya yüklemek onu değiştirecektir.','Action'=>'Eylem','Actions'=>'İşlemler','active'=>'aktif','Active Languages'=>'Aktif Diller','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktif diller: desteklemek istediğiniz her dili ekleyin. Her dil, bir URL öneki veya alt alan adı ve sayfa &lt;head&gt; bölümünde bir hreflang etiketi alır.','Active Provider'=>'Aktif Sağlayıcı','Add entry'=>'Giriş ekle','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Taslağı geliştirmek için talimatlar ekleyin — örneğin, daha kısa yapın, bir sonuç bölümü ekleyin, daha resmi bir dil kullanın, SSS bloğu ekleyin…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Taslağı geliştirmek için talimatlar ekleyin — ör. daha kısa yapın, sonuç bölümü ekleyin, daha resmi bir dil kullanın…','Add new entry'=>'Yeni giriş ekle','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Bir satıra bir terim ekleyin. Hem kaynak terim hem de hedef gösterim gereklidir. Dil çifti, hangi çeviri işleri için kısıtlamanın geçerli olduğunu belirler.','Adds a link to the home page so visitors can browse in their language.'=>'Ziyaretçilerin kendi dillerinde gezinebilmeleri için ana sayfa bağlantısı ekler.','Administrators only (manage_options)'=>'Yöneticiler sadece (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Birincil dili değiştirdikten sonra, URL yönlendirmesinin güncellenmesi için kalıcı bağlantıları (aşağıdaki bölüm) temizleyin.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'URL yapılandırma ayarlarını değiştirdikten sonra (yol öneki ↔ alt alan adı), her zaman Ayarlar → Kalıcı Bağlantılar bölümüne gidin ve Yeniden Yazma Kurallarını Temizle\'ye tıklayın.','AI Behaviour Preset'=>'Yapay Zeka Davranış Ön Ayarı','AI cache cleared. %d entry was removed.'=>'AI önbelleği temizlendi. %d giriş kaldırıldı.' . "\0" . 'AI önbelleği temizlendi. %d giriş kaldırıldı.','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'AI Önbelleği: önbelleğe alınmış AI yanıtlarını vuruş sayılarıyla listeler. Tüm önbelleği veya tek bir gönderinin girişlerini temizleyin. Bir çeviri değişikliğini test etmeden önce "Temizle" kullanın — önbelleğe alınmış sonuçlar, AI ön ayarını veya modeli değiştirdiğinizde bile, önbellek girdisi kaldırılana kadar geri döner.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'AI özellikleri isteğe bağlıdır. Dil yönlendirme, hreflang, dil değiştirme ve çeviri grup sistemi, bir sağlayıcı yapılandırılmadan çalışır.','AI Limits & Security'=>'AI Sınırları ve Güvenlik','AI provider returned an empty response.'=>'AI sağlayıcısı boş yanıt döndürdü.','AI Usage'=>'Yapay Zeka Kullanımı','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'120–160 karakter hedefleyin. Boş bırakın, alıntı yedek kullanılsın.','All time'=>'Tüm zamanlar','Allow editors to lock individual blocks'=>'Editörlerin bireysel blokları kilitlemesine izin ver','Allow Gutenberg template-editing mode on post screens'=>'Yazı ekranlarında Gutenberg şablon düzenleme moduna izin ver','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Ayrıca dil atamalarını, çeviri ilişkilerini, meta açıklamaları, sözlüğü ve Çeviri Belleğini kaldırırken, eklenti kaldırılır.','Also generate meta description'=>'Ayrıca meta açıklaması oluştur','Alternative (server-side):'=>'Alternatif (sunucu tarafı):','An unknown error occurred.'=>'Bilinmeyen bir hata oluştu.','and'=>'ve','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'herhangi','API calls saved by cache'=>'Önbelleğe alınmış API çağrıları','API Key'=>'API Anahtarı','API Keys'=>'API Anahtarları','API Keys Tab'=>'API Anahtarları Sekmesi','API Response Cache'=>'API Yanıt Önbelleği','Applied ✓'=>'Uygulandı ✓','Apply failed — please try again.'=>'Uygulama başarısız oldu — lütfen tekrar deneyin.','Apply to Block'=>'Bloklara Uygula','Apply to Editor'=>'Editöre uygula','Apply to Footnote'=>'Dipnota Uygula','Apply to Meta Description'=>'Meta Açıklamasına Uygula','Apply translation'=>'Çeviriyi uygula','Applying…'=>'Uygulanıyor…','Approximate size'=>'Yaklaşık boyut','Archive'=>'Arşiv','Archive: %s'=>'Arşiv: %s','Authors and above (edit_published_posts)'=>'Yazarlar ve üzeri (edit_published_posts)','Behavior'=>'Davranış','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Davranış: AI ön ayarını seçin (Literal, Balanced, Creative), site genelinde özel istem prompt talimatları ekleyin, otomatik gönderi kaydetme çevirisini etkinleştirin veya devre dışı bırakın ve Çeviri Belleği\'ni yapılandırın.','Block Content'=>'Blok İçeriği','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Ziyaretçinin dilinde çeviri yoksa, sayfa kendi dilinde gösterildiğinde nazikçe bir bildirim gösterir. Lingua Forge yönlendiricisinin LINGUAFORGE_LANG_FALLBACK_ACTIVE sinyali tarafından tetiklenir — istek bölgesi için çeviri varsa hiçbir şey yayınlamaz.','Block Editor'=>'Blok Düzeni','block keywordfallback'=>'Yedekleme','block keywordi18n'=>'i18n','block keywordlanguage'=>'Dil','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'Çeviri','Block locking'=>'Blok kilitleme','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Özel gönderi türleri için kaydedilen blok desenleri. Bir dil varyantı üretmek için Çevir düğmesini kullanın. Çevirilen içerik burada kaydedilir ve blok düzenleyici Desen ekleyicisinden herhangi bir CPT gönderisine kopyalanabilir veya Senkronize Desen (Yeniden Kullanılabilir Blok) için başlangıç noktası olarak kullanılabilir.','block titleMissing Translation Notice'=>'Çeviri Eksik Bildirimi','Block translation reuses'=>'Blok çeviri tekrarlarını','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Blok seviyesinde çeviri önbelleği, gönderiler arasında paylaşılır. Etkinleştirildiğinde, aynı bloklar (aynı biçim, dil çifti ve sözlük) tekrar AI çağrısı yapmadan bellekten sunulur. Ayarlar → Davranış bölümünden yapılandırın.','Browser language redirect'=>'Tarayıcı dili yönlendirmesi','Built-in preset instructions:'=>'Yerleşik ön ayar talimatları:','Bulletize (•-prefixed)'=>'Madde işaretleri (•-ön ekli)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Yeniden kullanılabilir içeriklerin (paylaşılan altbilgiler, kenar çubukları, akordiyonlar, standart hukuk bölümleri) API çağrısı yapmadan önce önbelleğe alınmasını sağlar. Etkinleştirildiğinde, çeviri akışı her yazıyı bloklara ayırır, her bloğu önbellekte arar ve yalnızca önbelleğe alınmamış blokları tek bir toplu istekle yapay zekaya gönderir. Terim sözlüğü düzenlemeleri ve Uyumluluk ön ayarı değişiklikleri otomatik olarak etkilenen önbelleğe alınmış çevirileri geçersiz kılar. İstatistikleri görüntüle ve önbelleği temizle.','cached'=>'önbelleğe alındı','Cached API responses'=>'Önbelleğe alınmış API yanıtları','Cached block translations'=>'Önbelleğe alınmış blok çevirileri','Cancel'=>'İptal','Cannot determine target language from slug.'=>'Hedef dili slug\'dan belirlenemiyor.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Site\'nin ne kadar AI kullanımı yapabileceğini sınırla ve hangi kullanıcı rollerinin ücretli AI çağrılarını tetikleyebileceğini kısıtla. Bu, zaten tek kullanıcı kaçak döngülerine karşı koruyan kullanıcı başına oran sınırının (30 istek / dakika, sabit kodlu) üzerine oturur.','chars'=>'karakterler','Chunk translated'=>'Parça çevrildi','Chunk translated to:'=>'Parça çevrildi:','Clear'=>'Temizle','Clear All'=>'Tümünü Temizle','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Tüm önbelleğe alınmış AI sonuçlarını temizlesin mi? Gelecekteki istekler, önbellek yeniden oluşturulana kadar yeni API çağrılarını tetikleyecektir.','Clear API Response Cache'=>'API Yanıt Önbelleğini Temizle','Clear Debug Files'=>'Hata ayıklama Dosyalarını Temizle','Clear hints'=>'İpucunu temizle','Clear input'=>'Girdiyi temizle','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Tüm Çeviri Belleğini temizle? Gelecekteki çeviriler önbelleği yeniden oluşturacaktır.','Clear Translation Memory'=>'Çeviri Belleğini Temizle','Close'=>'Kapat','Close language panel'=>'Dil panelini kapat','Close popover'=>'Açılır pencereyi kapat','Compliance Preset'=>'Uyumluluk Ön Ayarı','Content generated'=>'İçerik oluşturuldu','Content Generator'=>'İçerik Üreteci','Content ready'=>'İçerik hazır','Contributors and above — default (edit_posts)'=>'Katkıda bulunanlar ve üzeri — varsayılan (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'AI\'ye gönderilen içerik miktarını ve yanıtın ne kadar büyük olabileceğini kontrol et. Bir alanı boş bırakmak yerleşik varsayılanı kullanır (yer tutucu olarak gösterilir). Büyük sayfalar kesiliyorsa bu değerleri artırın; API maliyetlerini azaltmak için düşürün.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'AI İçerik Üreteci özelliği için token bütçesi ve giriş limitlerini kontrol eder. Alanları boş bırakmak, yerleşik varsayılanları kullanır.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Bir yönetici eklentiyi Kaldırmak için Eklentiler → Yüklü Eklentiler → Sil\'den sildiğinde ne olacağını kontrol eder. Eklenti ayarları ve AI önbellekleri her zaman kaldırılır. Dil atamaları ve çeviri ilişkileri varsayılan olarak korunur, böylece yanlışlıkla kaldırma veya yeniden yükleme kaldığı yerden devam edebilir.','Conversational'=>'Konuşma Dili','Copied ✓'=>'Kopyalandı ✓','Copy'=>'Kopyala','Copy markup'=>'İşaretlemeyi kopyala','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Sonucu kopyalayın ve gerekirse yapıştırın (ör. doğrudan dipnot alanına).','Copy to safe storage'=>'Güvenli depolamaya kopyala','Could not add entry: source term and target term are required.'=>'Giriş eklenemedi: kaynak terim ve hedef terim gereklidir.','Could not copy the file. Check that the uploads folder is writable.'=>'Dosya kopyalanamadı. Yükleme klasörünün yazılabilir olup olmadığını kontrol edin.','Could not instantiate the provider.'=>'Sağlayıcı başlatılamadı.','Could not save the file. Check that the uploads folder is writable.'=>'Dosya kaydedilemedi. Yükleme klasörünün yazılabilir olup olmadığını kontrol edin.','Could not save the glossary entry.'=>'Terimlik giriş kaydedilemedi.','CPT Block Patterns'=>'CPT Blok Desenleri','Create'=>'Oluştur','Create missing'=>'Eksik olanı oluştur','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'"%s" gönderi türü için çeviri oluşturmak, aktif bir entegrasyon gerektirir. Lütfen gerekli entegrasyonun yüklü ve aktif olduğundan emin olun.','Creating…'=>'Oluşturuluyor…','Creative / Marketing'=>'Yaratıcı / Pazarlama','Creative / Marketing instructions'=>'Yaratıcı / Pazarlama talimatları','Current content (will be overwritten)'=>'Mevcut içerik ( üzerine yazılacak)','Current title'=>'Mevcut başlık','Current: {current}'=>'Mevcut: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Şu anda %s sabitinden miras alınmıştır. Buraya bir değer seçmek, onu geçersiz kılar.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Şu anda, blok-yorum öznitelik yer tutucuları (wp:details özet alanları vb.) kullanan yazılar için atlanır — bunlar mevcut tek çağrı çeviri yoluna geçer.','Currently:'=>'Şu anda:','Custom'=>'Özel','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Günlük AI kotası aşıldı (%1$d istek). UTC %2$s\'de sıfırlanır.','Daily request limit'=>'Günlük istek sınırı','Debug Files'=>'Hata Ayıklama Dosyaları','Debug files cleared. %d file was removed.'=>'Hata ayıklama dosyaları temizlendi. %d dosya kaldırıldı.' . "\0" . 'Hata ayıklama dosyaları temizlendi. %d dosya kaldırıldı.','Debug logging'=>'Hata ayıklama günlüğü','Debug logging disabled.'=>'Hata ayıklama günlüğü devre dışı bırakıldı.','Debug logging enabled.'=>'Hata ayıklama günlüğü etkinleştirildi.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Hata ayıklama: AI istemlerini ve API yanıtlarını yerel bir dosyaya yakalamak için hata ayıklama günlüğünü etkinleştirin. Sorun giderme sonrası devre dışı bırakın — hata ayıklama modu her AI isteğinde bir dosya yazar.','Delete'=>'Sil','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Hata ayıklama dizinindeki tüm .txt dosyalarını silmek istiyor musunuz? Dizin kendisi kalacak, böylece gelecekteki hata ayıklama yazıları düzgün şekilde kaydedilir.','Delete all files for this override (both .mo and .po)?'=>'Bu geçersiz kılma için tüm dosyaları silmek istiyor musunuz? (hem .mo hem de .po)','Delete content data on uninstall'=>'Kaldırma sırasında içerik verilerini sil','Delete this glossary entry?'=>'Bu terimlik giriş silinsin mi?','Describe what to write — topic, key points, structure…'=>'Ne yazılacağını anlatın — konu, ana noktalar, yapı…','Directory'=>'Dizin','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'İstem ayarlaması sırasında veya her isteğin AI sağlayıcısına ulaşması gerektiğinde devre dışı bırakın. Devre dışı bırakmak, önbelleğe alınmış girdileri silmez — yeniden etkinleştirme onları geri yükler. Devre dışı bırakıldığında, yoğun sitelerde API harcamalarını hemen artırmak beklenir.','Display'=>'Görüntüleme','Displays the Lingua Forge language switcher.'=>'Lingua Forge dil değiştiricisini gösterir.','Documentation'=>'Belgeler','Done'=>'Tamamlandı','Done — {done} of {total} post(s) fixed.'=>'Tamamlandı — {done} gönderi düzeltildi, toplam {total}.','Down'=>'Aşağı','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'WordPress.org\'dan doğrudan bir WordPress çekirdek dil paketi indirip yükleyin. Yüklendikten sonra, yerel ayar URL yönlendirmesi ve AI çeviri akışı için kullanılabilir hale gelir. Mevcut diller listesi talep üzerine alınır — aşağıdaki düğmeye tıklayarak yükleyin.','Dropdown direction'=>'Açılır menü yönü','Editors and above (edit_others_posts)'=>'Editörler ve üzeri (edit_others_posts)','Enable API response caching'=>'API yanıt önbelleklemesini etkinleştir','Enable block-level translation cache reuse across posts'=>'Blok seviyesinde çeviri önbelleği yeniden kullanımını etkinleştir','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'En az bir AI sağlayıcısı için API anahtarınızı girin. Anahtarlar, AES-256-GCM kullanılarak siteye özgü bir gizli anahtar (LINGUAFORGE_SECRET) ile dinlenirken şifrelenir. Anahtarı değiştirmeden veritabanı dışa aktarımını paylaşmayın.','environment variable'=>'ortam değişkeni','Error'=>'Hata','Expand'=>'Genişlet','Expected: {expected}'=>'Beklenen: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Ek rehberlik — ton, stil, kısıtlamalar, hedef kitle…','Extra guidance — tone, style, constraints…'=>'Ek rehberlik — ton, stil, kısıtlamalar…','Failed. Please try again.'=>'Başarısız oldu. Lütfen tekrar deneyin.','Feature'=>'Özellik','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Özellikler iki seviyeye ayrılmıştır. Her seviye ve sağlayıcı için tam model tanımlayıcısını girin. Yer tutucu olarak gösterilen yerleri boş bırakın. Yalnızca aktif sağlayıcının modelleri çalışma zamanında çağrılır — diğerlerini önceden yapılandırın, eğer değiştirmeyi planlıyorsanız.','File copied to safe storage successfully.'=>'Dosya güvenli depolamaya başarıyla kopyalandı.','Files'=>'Dosyalar','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Dosyalar aşağıdaki dizine kaydedilir. Çeviri sorunlarını teşhis etmek için kullanışlıdır — ihtiyacınız olanı aldıktan sonra kapatın, böylece dosyalar birikmez. Ayrıca wp-config.php\'den `define( \'LINGUAFORGE_AI_DEBUG\', true );` ile zorlayabilirsiniz, bu da anahtarı geçersiz kılar.','Filter'=>'Filtre','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Hata ayıklama çıktısını gizli olmayan bir konuma yönlendirmek için linguaforge_debug_dir filtresi ile kullanın.','Fix'=>'Düzenle','Fix All'=>'Tümünü Düzelt','Fix all links'=>'Tüm bağlantıları düzelt','Fix all parts'=>'Tüm parçaları düzelt','Fix Links'=>'Bağlantıları Düzelt','Fix Nav'=>'Gezintiyi Düzelt','Fix Parts'=>'Parçaları Düzelt','Fix Template'=>'Şablonu Düzelt','Fixing {n} / {total}…'=>'{n} / {total} düzeltiliyor…','Fixing…'=>'Düzenleniyor…','Flush Permalink Rules'=>'Kalıcı Bağlantı Kurallarını Temizle','Flush Permalinks'=>'Kalıcı Bağlantıları Temizle','Footnote Content'=>'Dipnot İçeriği','footnote(s) translated — applied together with content.'=>'Dipnot(lar) çevrildi — içerikle birlikte uygulandı.','Footnotes'=>'Dipnotlar','Footnotes payload (advanced)'=>'Dipnotlar yükü (ileri düzey)','Forbidden'=>'Yasaklandı','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php\'deki LINGUAFORGE_AI_DEBUG sabiti tarafından ZORUNLU olarak KAPATILDI. Bu anahtarı kaldırın, böylece buradan bu anahtarı kontrol edebilirsiniz.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'wp-config.php\'deki LINGUAFORGE_AI_DEBUG sabiti tarafından ZORUNLU olarak AÇILDI. Bu anahtarı kaldırın, böylece buradan bu anahtarı kontrol edebilirsiniz.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'<strong>{total}</strong> içindeki <strong>{parts}</strong> parça bulundu. <strong>{scanned}</strong> taranan gönderi için.','From'=>'İle','Front Page'=>'Ana Sayfa','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'FSE yerelleştirme: bu sekmeden doğrudan Tam Site Düzenleme şablonları ve şablon parçalarında iskelet, çeviri ve bağlantıları düzeltin.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Aktif temadan tohumlanan FSE şablonları. Site Düzenleyicisinde oluşturun ve özelleştirin.','Full Article'=>'Tam Makale','Full post'=>'Tam gönderi','General'=>'Genel','Generate'=>'Oluştur','Generate Content'=>'İçerik Oluştur','Generate content…'=>'İçerik oluştur…','Generate Excerpt'=>'Özet Oluştur','Generate Meta Description'=>'Meta Açıklaması Oluştur','Generated Content'=>'Oluşturulan İçerik','Generated meta description'=>'Oluşturulan meta açıklaması','Generating…'=>'Oluşturuluyor…','Generation failed.'=>'Oluşturma başarısız oldu.','Getting started'=>'Başlangıç','Global AI preset'=>'Küresel Yapay Zeka ön ayarı','Global default (%s)'=>'Global varsayılan (%s)','Glossary'=>'Terim Sözlüğü','Glossary entry added.'=>'Terimlik girişi eklendi.','Glossary entry removed.'=>'Terimlik girişi kaldırıldı.','Glossary Tab'=>'Sözlük Sekmesi','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Gizle','Hints'=>'İpuçları','Home link text'=>'Ana sayfa bağlantı metni','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Çeviride nasıl görünmesi gerektiği. Aynı değeri kaynak terimle girin, böylece AI\'nin aynen korumasını sağlayın.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Simge + etiket','Icon only'=>'Sadece simge','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'İşaretlenirse, eklentiyi kaldırmak, bu sitedeki tüm dil atamalarını, çeviri ilişkilerini, meta açıklamaları, sayfa ön ayarlarını, AI sözlüğünü ve Çeviri Belleğini kalıcı olarak silecektir. Bu geri alınamaz. Çok dilli desteği tamamen kaldırmıyorsanız, işaretlemeyin.','Improve writing'=>'Yazımı geliştir','Informative'=>'Bilgilendirici','Input tokens'=>'Girdi tokenleri','Install'=>'Yükle','Install a Language'=>'Bir Dil Yükle','Installing…'=>'Yükleniyor…','Instructions (optional)'=>'Talimatlar (isteğe bağlı)','Instructions / key points'=>'Talimatlar / ana noktalar','Integration API'=>'Entegrasyon API\'si','Internal Link Fixer'=>'İç Bağlantı Düzeltici','Introduction only'=>'Sadece Giriş','Invalid file reference.'=>'Geçersiz dosya referansı.','Invalid filename.'=>'Geçersiz dosya adı.','Invalid language.'=>'Geçersiz dil.','Invalid locale code.'=>'Geçersiz yerel kod.','Invalid or primary language.'=>'Geçersiz veya ana dil.','Invalid post type.'=>'Geçersiz gönderi türü.','Invalid template part.'=>'Geçersiz şablon parçası.','Invalid template type.'=>'Geçersiz şablon türü.','Key points, ideas, or structure to build from…'=>'Anahtar noktalar, fikirler veya yapı...','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Anahtarlar, WordPress veritabanında saklanmadan önce AES-256-CBC ile şifrelenir. Şifreleme sırrı, WordPress kimlik doğrulama tuzlarınızdan (wp-config.php) türetilir, bu nedenle düz metin anahtarlar asla veritabanına dokunmaz.','Language'=>'Dil','Language %s installed successfully.'=>'Dil %s başarıyla yüklendi.','Language (optional)'=>'Dil (isteğe bağlı)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Bu sunucuda dil yükleme devre dışı bırakılmıştır (DISALLOW_FILE_MODS ayarlanmış).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Bu sunucuda dil yükleme devre dışı bırakılmıştır. wp-config.php dosyasında DISALLOW_FILE_MODS sabiti ayarlanmıştır. Dil paketlerini manuel olarak WP-CLI ile yükleyin: wp language core install de_DE','Language label'=>'Dil etiketi','Language Overrides'=>'Dil Üzerinden Değişiklikleri','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Dil Üzerinden Geçersizlikler: Lingua Forge UI dizeleri için özel .po/.mo geçersizlik dosyalarını yönetin. Bu, eklenti dosyalarını doğrudan düzenlemek yerine kullanılır — geçersizlikler güncellemelerden sonra da kalır.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Dil paketi yüklemesi başarısız oldu. Dil zaten yüklü olabilir, yerel kod yanlış olabilir veya sunucunuz dosya yazma işlemlerini engelliyor olabilir.','Language Setup'=>'Dil Kurulumu','Language Switcher'=>'Dil Değiştirici','Language switcher'=>'Dil değiştirme aracı','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Temanın dil özelinde kopyaları. İskelet oluşturulduktan sonra, şablonlar dil özelinde parçayı referans gösterecek şekilde güncellenir.','Language:'=>'Dil:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Yönlendirici tarafından şu anda bilinen diller (kurulu WordPress yerel paketleri ve birincil dilden türetilmiştir). Yönlendirme ve çeviri için daha fazla dil kullanılabilir hale getirmek üzere aşağıdaki bölümde ek dil paketleri yükleyin.','Last 30 days'=>'Son 30 gün','Last 7 days'=>'Son 7 gün','Lead paragraph (≤60 w)'=>'Ön paragraf (≤60 kelime)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Bir model alanını boş bırakın, bu katman için yerleşik varsayılanı kullanın. Yer tutucu metin, hangi modelin kullanılacağını gösterir.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Marka isimleri ve dilden bağımsız terimler için boş bırakın, bunlar hangi dilden çeviri yapılıyor olursa olsun zorunludur.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Bu girdiyi tüm hedef dillere uygulamak için boş bırakın — marka isimleri, kısaltmalar ve her çeviride aynen korunması gereken terimler için idealdir.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Boş bırakmak mevcut anahtarı korur. Yenisini girerek değiştirebilirsiniz.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Varsayılanı kullanmak için boş bırakın. Kaydedilen bir geçersiz kılmayı temizlemek, varsayılanı bir sonraki kayıtta geri yükler.','Legal / Compliance'=>'Yasal / Uyumluluk','Legal / Compliance instructions'=>'Yasal / Uyumluluk talimatları','Light'=>'Hafif','Light (default — fast and cost-effective)'=>'Hafif (varsayılan — hızlı ve maliyet etkin)','Light (fast and cost-effective — Haiku / Flash)'=>'Hafif (hızlı ve maliyet etkin — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Hafif: meta açıklamaları ve özet oluşturma için kullanılır — hızlı, düşük maliyetli.','Limit results to pages in the given Lingua Forge language code.'=>'Sonuçları verilen Lingua Forge dil kodundaki sayfalara sınırla.','Limits'=>'Sınırlar','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge, çok dilli yönlendirme, AI destekli çeviri, hreflang SEO etiketleri ve dil değiştirme aracını WordPress sitenize ekler.','Lingua Forge AI Tools'=>'Lingua Forge AI Araçları','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge, dil genelinde düzenleyici davranışı tutarlı tutmak için varsayılan olarak iki Gutenberg özelliğini sınırlar. Tam Gutenberg / FSE yeteneklerine ihtiyacınız olduğunda buradan katılın.','Lingua Forge Settings'=>'Lingua Forge Ayarları','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge, gereksiz AI API çağrılarını önlemek için iki bağımsız önbellek katmanı kullanır. Her birini incelemek ve yönetmek için aşağıdaki sekmeleri kullanın.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge, sağlayıcı başına iki model katmanı kullanır:','Lingua Forge — Quick Translate'=>'Lingua Forge — Hızlı Çeviri','Lingua Forge — Settings'=>'Lingua Forge — Ayarlar','link(s)'=>'bağlantı','Links'=>'Bağlantılar','Load available languages'=>'Mevcut dilleri yükle','Loading…'=>'Yükleniyor…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate, özel çevirilerini wp-content/languages/loco/ dizininde saklar — bu konum, WP çekirdek güncellemesi, eklenti yeniden yüklemesi veya Loco Translate\'in kaldırılmasıyla sessizce silinebilir. Dosyaları buraya kopyalamak, bunları Lingua Forge i18n-overrides dizinine taşır ve bu dizin tüm bu olaylar sırasında kalıcıdır ve her istekte otomatik yüklenir.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Güvenli Depolamaya Kopyala','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'AI özelliklerini tetiklemek için izin verilen en düşük WordPress yeteneği. Çok yazarlı sitelerde bunu sıkılaştırmak, Katkıda Bulunanlar veya deneme hesaplarının ücretli AI çağrılarını çalıştırmasını engeller. Özellik başına override etmek için linguaforge_required_capability filtresini kullanın.','Maintenance'=>'Bakım','Maintenance Tab'=>'Bakım Sekmesi','Make casual'=>'Samimi yap','Make concise'=>'Özlü yap','Make formal'=>'Resmi yap','Mark citations needed'=>'Alıntılar gerekirse işaretle','Max context characters'=>'Maksimum bağlam karakterleri','Max hints characters'=>'İpucu karakterleri için maksimum sınır','Max input characters'=>'Maksimum giriş karakterleri','Max output tokens'=>'Maksimum çıktı token sayısı','Maximum characters accepted from the input field. Default: 8 000.'=>'Giriş alanından kabul edilen maksimum karakter sayısı. Varsayılan: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'İpucu sağlanmadığında, AI\'ye iletilen mevcut gönderi içeriğinin maksimum karakter sayısı. Varsayılan: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'İpucu alanından okunan maksimum karakter sayısı. Varsayılan: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'AI\'ye iletilen gönderi içeriğinin maksimum karakter sayısı. 0 ise sınır yok — tam içerik her zaman gönderilir (önerilir). Sağlayıcınızın sıkı bir bağlam penceresi varsa, sıfır olmayan bir değer ayarlayın. İçerik kısaltıldığında PHP hata günlüğüne uyarı yazılır.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'AI\'nin tek bir çeviri yanıtında üretebileceği maksimum token sayısı. Bir çeviri sessizce kesilirse, bu değeri artırın. Varsayılan: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Her üretim çalışması için AI\'nin üretebileceği maksimum token sayısı. Tam makaleler kesiliyorsa artırın. Varsayılan: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'AI\'nin her hızlı çeviri için üretebileceği maksimum token sayısı. Varsayılan: 2.000.','Meta Description'=>'Meta Açıklaması','Meta Description, Excerpt Generator'=>'Meta Açıklaması, Alıntı Üretici','Minimum role'=>'En düşük rol','Missing pattern name or language.'=>'Desen adı veya dil eksik.','Mode'=>'Mod','Model'=>'Model','Model tier'=>'Model seviyesi','Models'=>'Modeller','Models Tab (General)'=>'Modeller Sekmesi (Genel)','Most recent cached block'=>'En son önbelleğe alınmış blok','Most recent cached response'=>'En son önbelleğe alınmış yanıt','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'WordPress için çok dilli yönlendirme, SEO meta etiketleri ve AI içerik araçları. Dil tespiti, URL yönlendirmesi, hreflang, meta açıklamaları ve AI destekli alıntı, meta ve çeviri özelliklerini birleştirir.','Name displayed in this language. Leave empty to use the source name.'=>'Bu dilde görüntülenen isim. Kaynak ismi kullanmak için boş bırakın.','Navigation'=>'Gezinti','Navigation has no content to translate.'=>'Gezinmenin çevrilecek içeriği yok.','Navigation not found.'=>'Gezinme bulunamadı.','Navigation posts are translated via the Router tab, not this button.'=>'Gezinme gönderileri, bu düğme yerine Router sekmesi aracılığıyla çevrilir.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Gezinti çevirisi, aktif bir AI sağlayıcısı gerektirir. API Anahtarları sekmesinde bir API anahtarı yapılandırın.','Navigations'=>'Gezintiler','Network error — could not reach the WordPress AJAX endpoint.'=>'Ağ hatası — WordPress AJAX uç noktasına ulaşılamadı.','No %s version found in this translation group.'=>'Bu çeviri grubunda %s sürümü bulunamadı.','No AI provider configured.'=>'AI sağlayıcısı yapılandırılmadı.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Seçilen pencerede Yapay Zeka kullanımı kaydı yok (%s). Yukarıdaki daha geniş bir aralık seçin.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Henüz Yapay Zeka kullanımı kaydedilmedi. Bir editör çeviri yaparsa, meta açıklaması oluşturursa veya başka bir Yapay Zeka özelliği kullanırsa, toplamlar burada görünecek.','No API key configured for this provider.'=>'Bu sağlayıcı için yapılandırılmış API anahtarı yok.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Yerleşik talimat yok — her AI özelliği kendi ayarlanmış varsayılanlarını kullanır. Aşağıdaki Özel istem alanını doldurarak kendi site genelinde kurallarınızı ekleyin.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Henüz özel Loco Translate dosyası bulunmuyor. Bir çeviri kaydettiğinizde burada görünürler.','No file was selected.'=>'Hiç dosya seçilmedi.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Mevcut filtreyle eşleşen terimlik girişi yok. Tüm girişleri görmek için filtreyi temizleyin veya aşağıda yeni bir giriş ekleyin.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Henüz terimlik girişi yok. Çevirilerde terimlerin uygulanmaya başlaması için aşağıda bir tane ekleyin.','No internal links found to update.'=>'Güncellenecek dahili bağlantı bulunamadı.','No language-specific template parts found to map.'=>'Haritalanacak dil\'e özgü şablon parçası bulunamadı.','No navigation references needed updating.'=>'Güncellenecek gezinme referansı yok.','No override files uploaded yet.'=>'Henüz geçersiz kılma dosyası yüklenmedi.','No response from provider — check the error log for details.'=>'Sağlayıcıdan yanıt alınamadı — detaylar için hata günlüğünü kontrol edin.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'İkincil dil yapılandırılmamış. Şablon iskeletini etkinleştirmek için yukarıdaki dil paketini yükleyin.','No source content found to translate.'=>'Çeviri yapılacak kaynak içerik bulunamadı.','No source page linked yet.'=>'Henüz kaynak sayfa bağlantısı yok.','No template part references needed updating.'=>'Güncellenecek şablon parçası referansı yok.','No {lang} translation registered (TRID missing)'=>'{lang} çevirisi kaydedilmedi (TRID eksik)','Notes'=>'Notlar','Notice message'=>'Bildirim mesajı','Notice settings'=>'Bildirim ayarları','Oldest cached block'=>'En eski önbelleğe alınmış blok','Oldest cached response'=>'En eski önbelleğe alınmış yanıt','Only .mo files are accepted.'=>'Sadece .mo dosyaları kabul edilir.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Editörler için isteğe bağlı bağlam (ör. "ASIC = Uygulamaya Özgü Entegre Devre; teknik bağlamlarda İngilizce korunmalı").','Output'=>'Çıktı','Output tokens'=>'Çıktı tokenleri','overridden'=>'geçersiz kılındı','Override file deleted.'=>'Geçersiz kılma dosyası silindi.','Override file uploaded successfully.'=>'Geçersiz kılma dosyası başarıyla yüklendi.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Bu sayfadaki Çeviri ve İçerik Oluşturma için Yapay Zeka ön ayarını geçersiz kılar. Diğer tüm özellikler her zaman küresel ön ayarı kullanır.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Bu sayfadaki Çeviri ve İçerik Oluşturma için Yapay Zeka ön ayarını geçersiz kılar. Site genelinde özel istem talimatları (Ayarlar → Davranış) her isteğe eklenir, bu seçimden bağımsızdır.','Overview'=>'Genel Bakış','Page'=>'Sayfa','Part'=>'Parça','Paste a footnote, sentence, or any snippet here…'=>'Buraya bir dipnot, cümle veya herhangi bir parçayı yapıştırın…','Paste text, or select text in the editor first…'=>'Metni yapıştırın veya önce düzenleyicide metni seçin…','Paste text, or select text on the page first…'=>'Metni yapıştırın veya önce sayfada metni seçin…','Paste your API key…'=>'API anahtarınızı yapıştırın…','Path prefix — example.com/de/'=>'Yol öneki — example.com/tr/','Pattern'=>'Desen','Pattern has no content to translate.'=>'Desenin çevrilecek içeriği yok.','Pattern not found.'=>'Desen bulunamadı.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Desen çevrildi ve kaydedildi. İçeriği blok düzenleyici Desen ekleyicisi aracılığıyla CPT gönderinize yapıştırın veya Yeniden Kullanılabilir Blok için başlangıç noktası olarak kullanın.','Pattern translation failed.'=>'Desen çevirisi başarısız oldu.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'AI tarafından oluşturulan çeviriler, meta açıklamaları, özetler ve içerik için gönderi başına önbellek. Her zaman aktiftir — ayrı bir anahtar açma/kapama gerekmez. İçerik veya AI sağlayıcısı/model değiştiğinde girdiler otomatik olarak geçersiz kılınır. Yeniden çeviri için araç çubuğundaki "↺ Yeniden Çevir" düğmesini veya aşağıdaki Temizle\'yi tıklayın.','Permalink rules flushed successfully.'=>'Kalıcı bağlantı kuralları başarıyla temizlendi.','Permission denied.'=>'İzin reddedildi.','Persuasive'=>'İkna edici','PHP constant'=>'PHP sabiti','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Çevirilmemesi veya belirli bir şekilde gösterilmesi gereken terimleri sabitleyin (örneğin marka isimleri, ürün isimleri, kısaltmalar). Sözlük kısıtlamaları, tüm özellikler için AI çevirisi talebine enjekte edilir: gönderi çevirisi, meta açıklaması, özet ve FSE şablon çevirisi.','Plain language'=>'Düz dil','Please enter some instructions first…'=>'Lütfen önce bazı talimatlar girin…','Please enter some text first…'=>'Lütfen önce biraz metin girin…','Post'=>'Gönderi','Post not found.'=>'Gönderi bulunamadı.','Post Types'=>'Gönderi Türleri','Prefilled from excerpt. Edit to override.'=>'Alıntıdan önceden dolduruldu. Üzerine yazmak için düzenle.','Primary Language'=>'Birincil Dil','Primary language'=>'Birincil dil','Primary language saved.'=>'Birincil dil kaydedildi.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Birincil dil: mevcut içeriğinizin yazıldığı dil. Tüm çeviriler bu dilden üretilir; değiştirmek, gönderileri taşımak veya silmek anlamına gelmez.','Processing…'=>'İşleniyor…','Provider'=>'Sağlayıcı','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Sağlayıcı herhangi bir metin döndürmedi. Ayrıntılı başarısızlık nedenini WordPress hata günlüğünde kontrol edin.','Quality'=>'Kalite','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kalite (varsayılan — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kalite (Sonnet / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kalite: gönderi çevirisi ve içerik oluşturma için kullanılır — daha yüksek kalite, daha yüksek maliyet.','Quick Translate'=>'Hızlı Çeviri','Quick Translation'=>'Hızlı Çeviri','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Hızlı Çeviri, snippet/parça modu için kullanılır — araç çubuğu, düzenleyici veya blok açılır pencerelerinden talep üzerine kısa pasajlar çevrilir. Yanıtları hızlı ve maliyet etkin tutmak için tam sayfa çeviriden ayrı, daha hafif bir yapılandırma kullanır.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Gutenberg\'in canLockBlocks özelliğini yeniden etkinleştirir. Katkıda bulunanların belirli blokları taşımalarını veya silmelerini engellemesi gereken düzenleyici şablonlar için kullanışlıdır.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'supportsTemplateMode\'u yeniden etkinleştirir. Yazı seviyesi şablon geçersiz kılmalarının kasıtlı olduğu Tam Site Düzenleme iş akışlarının temelidir.','Re-generates and updates the cached result.'=>'Önbelleğe alınmış sonucu yeniden oluşturur ve günceller.','Re-scan'=>'Yeniden Tara','Re-scanning…'=>'Tekrar tarama…','Re-translate'=>'Yeniden çevir','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Ziyaretçileri, tarayıcının Accept-Language başlığına göre tercih ettikleri dile yönlendirin','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Daha da iyileştir — örn. "daha kısa yap" veya "resmi ton kullan"…','Refine further:'=>'Daha fazla iyileştir:','Refinement'=>'Düzenleme','Refinement failed — please try again.'=>'Düzenleme başarısız oldu — lütfen tekrar deneyin.','Refining…'=>'Düzenleniyor…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'WordPress yeniden yazma kurallarını yeniden oluşturur, böylece URL önekleri, dil özelindeki takma adlar ve arşiv yeniden yazmaları senkronize olur. Birincil dil değiştirildikten veya yeni dil desteği eklendikten sonra gereklidir.','Remove stored key'=>'Depolanan anahtarı kaldır','Report an issue on GitHub'=>'GitHub\'da sorun bildir','Request failed — please try again.'=>'İstek başarısız oldu — lütfen tekrar deneyin.','Request failed.'=>'İstek başarısız oldu.','Request failed. Check your connection.'=>'İstek başarısız oldu. Bağlantınızı kontrol edin.','Request failed. Please try again.'=>'İstek başarısız oldu. Lütfen tekrar deneyin.','Requests'=>'İstekler','Reset'=>'Sıfırla','Result will appear here…'=>'Sonuç burada görünecek…','Retranslate'=>'Yeniden çevir','Retranslating…'=>'Yeniden çeviriliyor…','Review carefully — links and slugs not updated.'=>'Dikkatlice incele — bağlantılar ve slug\'lar güncellenmedi.','Review translation before applying'=>'Uygulamadan önce çeviriyi gözden geçirin','Revise'=>'Gözden Geçir','Revision'=>'Revizyon','Revision Type'=>'Revizyon Türü','Router'=>'Yönlendirici','Router Tab'=>'Yönlendirici Sekmesi','Save Debug Setting'=>'Hata ayıklama Ayarını Kaydet','Save Router Settings'=>'Yönlendirici Ayarlarını Kaydet','Save Settings'=>'Ayarları Kaydet','Save the post to persist changes.'=>'Değişiklikleri kalıcı hale getirmek için gönderiyi kaydedin.','Save Uninstall Setting'=>'Kaldırma Ayarını Kaydet','Saved to the meta description field when you apply.'=>'Uyguladığınızda meta açıklama alanına kaydedilir.','Scan failed: '=>'Tarama başarısız: ','Scan request failed. Please try again.'=>'Tarama isteği başarısız oldu. Lütfen tekrar deneyin.','Scanning posts for broken language links…'=>'Kırık dil bağlantıları için gönderileri tarıyor…','Search'=>'Arama','Search Results'=>'Arama Sonuçları','Security check failed — file path is not permitted.'=>'Güvenlik kontrolü başarısız — dosya yolu izin verilmedi.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Bir dil seçin ve onun FSE şablonlarını, şablon parçalarını ve gezinme menülerini yönetin.','Select language'=>'Dil seç','SEO character-count info'=>'SEO karakter sayısı bilgisi','Server setup (subdomain)'=>'Sunucu kurulumu (alt alan adı)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Tüm site genelinde varsayılan yapay zeka davranışını ayarlar. Bireysel yazılar, Lingua Forge meta kutusu aracılığıyla Çeviri ve İçerik Oluşturma için bunu geçersiz kılabilir.','Settings'=>'Ayarlar','Settings saved.'=>'Ayarlar kaydedildi.','Show home link'=>'Ana sayfa bağlantısını göster','Shown when no translation exists for the visitor\'s language.'=>'Ziyaretçinin dilinde çeviri yoksa gösterilir.','Single'=>'Tek','Single %s'=>'Tek %s','Single: %s'=>'Tek: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'UTC günü başına site genelinde AI istekleri tavanı (Hem Araç Çubuğu çevirileri hem de blok revizyonlarını sayar). Sayacı UTC gece yarısı sıfırlar. Devre dışı bırakmak için 0 olarak ayarlayın.','Size'=>'Boyut','Some link fixes failed.'=>'Bazı bağlantı düzeltmeleri başarısız oldu.','Some nav ref fixes failed.'=>'Bazı navigasyon referansı düzeltmeleri başarısız oldu.','Some part fixes failed.'=>'Bazı parça düzeltmeleri başarısız oldu.','Some parts could not be created.'=>'Bazı parçalar oluşturulamadı.','Some templates could not be created.'=>'Bazı şablonlar oluşturulamadı.','Some translations failed.'=>'Bazı çeviriler başarısız oldu.','Source file not found.'=>'Kaynak dosya bulunamadı.','Source lang'=>'Kaynak dil','Source language'=>'Kaynak dili','Source term'=>'Kaynak terim','Standard'=>'Standart','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standart, her özelliğin kendi ayarlanmış sıcaklığını kullanır: Çeviri T=0.2 (kesin), Hızlı Çeviri T=0.4, İçerik Üretici T=0.6 (yaratıcı). Diğer ön ayarlar, tüm özelliklerde tek bir sabit sıcaklık uygular.','Status'=>'Durum','Status / Actions'=>'Durum / İşlemler','Storytelling'=>'Hikaye Anlatımı','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Yasal, düzenleyici, tıbbi veya teknik içerik için katı koruma modu. Açık olduğunda, her yapay zeka özelliği düşük örnekleme sıcaklığı kullanır ve sistem istemine aşağıdaki ek açıklamayı ekler — terminoloji, makale numaraları, birimler, marka isimleri ve düzenleyici dil kelimesi kelimesine korunur, paraphrase edilmez.','Structured Outline'=>'Yapılandırılmış Taslak','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Alt alan adı modu, web sunucunuzun tüm dil alt alan adlarını (ör. tr.example.com) bu WordPress kurulumuna yönlendirmesini gerektirir. Modları değiştirdikten sonra kalıcı bağlantı kurallarını temizleyin ve önbellekleri boşaltın. Ana URL\'nizde www varsa (ör. www.example.com), alt alan adlarının doğru şekilde oluşturulması için lf_base_domain filtresini kullanarak çıplak kök alan adını ayarlayın.','Subdomain — de.example.com/'=>'Alt alan adı — tr.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Desteklenen sağlayıcılar: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Aynı anda yalnızca bir sağlayıcı aktiftir. Genel sekmeden aktif sağlayıcıyı seçin.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, özellik başına','Target lang'=>'Hedef dil','Target Language'=>'Hedef Dil','Target language'=>'Hedef dil','Target term'=>'Hedef terim','Target: 140–160 chars for optimal SERP display'=>'Hedef: 140–160 karakter, SERP gösterimi için','Technical'=>'Teknik','Technical / Scientific'=>'Teknik / Bilimsel','Technical / Scientific instructions'=>'Teknik / Bilimsel talimatlar','Template "%s" already exists.'=>'"%s" zaten var.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'"{expected}" şablonu mevcut değil — önce Site Düzenleyicisi\'nde oluşturun.','Template has no content.'=>'Şablonun içeriği yok.','Template mode'=>'Şablon modu','Template not found or not stored in the database.'=>'Şablon bulunamadı veya veritabanında saklanmadı.','Template part "%s" already exists.'=>'"%s" şablon parçası zaten var.','Template part has no content.'=>'Şablon parçasının içeriği yok.','Template part not found or not stored in the database.'=>'Şablon parçası bulunamadı veya veritabanında saklanmadı.','Template Parts'=>'Şablon Parçaları','Templates'=>'Şablonlar','Test connection'=>'Bağlantıyı test et','Testing…'=>'Test ediliyor…','Text domain / locale'=>'Dil alanı / yerel ayar','Text to translate'=>'Çevrilecek metin','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'API Yanıt Önbelleği, her AI isteğinin ham sonucunu depolar — çeviri, meta açıklama, özet ve içerik oluşturma — girişlerin özetine göre anahtarlandırılır (içerik, dil çifti, sağlayıcı, model). Aynı girişlerle yapılan sonraki istekler, API çağrısı yapılmadan önbellekten sunulur. Önbellek, Çeviri Belleği\'nden farklıdır: Çeviri Belleği, blok seviyesinde çalışır ve gönderiler arasında paylaşılır; API Yanıt Önbelleği ise özellik seviyesinde çalışır ve her gönderi için anahtarlandırılır.','The editor did not accept the content — please try again.'=>'Editör içeriği kabul etmedi — lütfen tekrar deneyin.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Hafif katman, yukarıdaki Modeller tablosunda yapılandırılmış hızlı modeli kullanır (varsayılan: Haiku / Flash). Parçalar için tam sayfa modu kadar çeviri doğruluğu gerekiyorsa Kalite\'ye geçin.','The phrase as it appears in the source text.'=>'Kaynak metinde göründüğü şekliyle ifade.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Birincil dil, sitenizin kökünde her zaman sunulur — yol modunda URL öneki yok, alt alan adında dil alt alan adı yok. Diğer tüm diller, aşağıdaki URL yapı ayarına bağlı olarak ya /lang/ yol öneki (ör. example.com/de/) ya da dil alt alan adı (ör. de.example.com) kullanır.','The source page has no footnotes.'=>'Kaynak sayfada dipnot yok.','The upload failed — please try again.'=>'Yükleme başarısız oldu — lütfen tekrar deneyin.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Bu dipnotlar kaynak sayfadan gelir ve burada sadece referans olarak gösterilir. Bunları blok düzenleyici kullanarak bu sayfaya ekleyin.','This is the source page. Footnotes are edited directly in the block editor.'=>'Bu kaynak sayfa. Dipnotlar doğrudan blok düzenleyicide düzenlenir.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Bu anahtar şu anda bir sunucu %s tarafından sağlanmaktadır ve burada kaldırılamaz. Üzerine yeni bir anahtar girerek veritabanı değeriyle üzerine yazabilirsiniz.','Tip: to reset a model to the built-in default, clear the field and save.'=>'İpucu: Bir modeli yerleşik varsayına sıfırlamak için alanı temizleyin ve kaydedin.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Kullanıcı tarafından belirlenen şifreleme sırrını kullanmak için (türetilmiş wp_salt değili yerine), bunu wp-config.php\'ye ekleyin:','Today'=>'Bugün','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Token tüketimi özellik, sağlayıcı ve model bazında toplanır. Her başarılı Yapay Zeka çağrısında kaydedilir; Test Bağlantısı pingsleri kasıtlı olarak hariç tutulur, böylece toplamlar sapmaz. Temel tablo günlük olarak özetlenir — görmek için aşağıdaki pencereden seçim yapın.','Tone'=>'Ton','tone'=>'tavır','Tone:'=>'Ton:','Too many AI requests. Please retry in %d seconds.'=>'Çok fazla AI isteği. Lütfen %d saniye içinde tekrar deneyin.','Total'=>'Toplam','Total tokens'=>'Toplam tokenler','Translate'=>'Çevir','Translate / Revise'=>'Çevir / Revize','Translate / Revise block'=>'Blok halinde çevir / Revize','Translate all'=>'Tümünü çevir','Translate chunk'=>'Parçayı çevir','Translate Content'=>'İçeriği Çevir','Translate missing'=>'Eksik çeviriyi çevir','Translate page…'=>'Sayfayı çevir…','Translated content'=>'Çevirilmiş içerik','Translated Names'=>'Çevirilen İsimler','Translated title'=>'Çevirilmiş başlık','Translated to:'=>'Çevirildi:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Çevirildi. Site Düzenleyici\'de inceleyin — dahili bağlantılar, gezinme URL\'leri ve şablon slug\'ları otomatik olarak güncellenmez.','Translating…'=>'Çeviriliyor…','Translation'=>'Çeviri','Translation Caching'=>'Çeviri Önbellekleme','Translation found but permalink could not be generated'=>'Çeviri bulundu ancak kalıcı bağlantı oluşturulamadı','Translation Limits'=>'Çeviri Sınırları','Translation Limits & Behavior'=>'Çeviri Sınırları ve Davranışları','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Çeviri Sınırları: hangi kullanıcı rollerinin AI çevirisini tetikleyebileceğini kontrol edin ve aylık token bütçesi belirleyin. Bütçeyi aşmak, ay reset olana kadar AI çağrılarını askıya alır.','Translation Memory'=>'Çeviri Belleği','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Çeviri Belleği, içerik karma, dil çifti, sağlayıcı ve model bazında AI sonuçlarını önbelleğe alır. Bir gönderiyi düzenlemek, önbellek girişini geçersiz kılar, böylece bir sonraki çeviri çağrısı taze bir sonuç alır.','Translation Memory cleared. %d cached block was removed.'=>'Çeviri Belleği temizlendi. %d önbelleğe alınmış blok kaldırıldı.' . "\0" . 'Çeviri Belleği temizlendi. %d önbelleğe alınmış blok kaldırıldı.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Çeviri Belleği: içerik karma başına tam çevrilmiş gönderiyi saklar. İçeriği değişmiş olsa da tüm gönderilerin yeniden çevrilmesini zorlamak istediğinizde temizleyin.','Translation workflow'=>'Çeviri iş akışı','Translation, Content Generator'=>'Çeviri, İçerik Üretici','Type'=>'Tür','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Kaldırma Davranışı','Uninstall setting saved.'=>'Kaldırma ayarı kaydedildi.','unknown error'=>'bilinmeyen hata','Unknown provider.'=>'Bilinmeyen sağlayıcı.','Up'=>'Yukarı','Upload .mo file'=>'.mo dosyası yükle','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Üçüncü taraf eklenti dizelerini geçersiz kılmak için derlenmiş .mo dosyalarını yükleyin — örneğin, "oda" yerine "daire" kullanan özel VikBooking çevirisi. Dosyalar WordPress adlandırma kurallarına uygun olmalı: {textdomain}-{locale}.mo (örneğin, vikbooking-ca.mo). Yükleme klasöründe saklanır ve eklenti güncellemelerine dayanır.','Upload Override'=>'Geçersiz kılma yükle','URL could not be mapped to a post — check the link target exists'=>'URL bir gönderiye eşlenemedi — bağlantı hedefinin var olup olmadığını kontrol edin','URL structure'=>'URL yapısı','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'URL yapısı: yol öneki modu (example.com/de/) sunucu değişikliği gerektirmez. Alt alan adı modu (de.example.com) ise joker DNS kaydı, joker SSL sertifikası ve web sunucusu yapılandırması değişikliği gerektirir — Sunucu Kurulumu kılavuzuna bakın.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Her alanı yapılandırmak için bu sayfanın üstündeki sekmeleri kullanın. Router sekmesindeki değişiklikler hemen etkili olur; AI anahtarları ve model ayarlarına yapılan değişiklikler bir sonraki AI isteğine uygulanır.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Dil çifti başına kullanıcı tarafından yönetilen terim tablosu. Girişler, AI\'nın tercih edilen terimleri tutarlı şekilde kullanması için çeviri sisteminin istemine eklenir — alan kelime dağarcığı ("kWp", "PPA", "bağlantı noktası"), değiştirilmemesi gereken marka isimleri ve standartlaştırılmış düzenleyici ifadeler için kritik önemdedir. Her iki dil alanı da isteğe bağlıdır: "Kaynak dili" boş bırakın, böylece giriş hangi dilden çeviri yapılıyor olursa olsun uygulanır; "Hedef dili" boş bırakın, böylece tüm hedef dillere aynı anda uygulanır.','Using custom meta description.'=>'Özel meta açıklaması kullanılıyor.','View'=>'Görüntüle','View built-in default'=>'Yerleşik varsayılanı görüntüle','View details'=>'Detayları görüntüle','View Lingua Forge details'=>'Lingua Forge detaylarını görüntüle','Visit plugin site'=>'Eklenti sitesini ziyaret et','Warning:'=>'Uyarı:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Hata ayıklama günlüğü etkinleştirildiğinde (aşağıdaki anahtar veya wp-config.php\'de LINGUAFORGE_AI_DEBUG tanımlanarak), Çeviri ve FSE şablon çeviri özellikleri sorun giderme için ham AI istemlerini ve yanıtlarını diske yazar. Bu bölümü, çıktıyı izlemek ve ihtiyacınız olanı aldıktan sonra temizlemek için kullanın — dosyalar büyük sayfalarda hızla büyüyebilir. Hedef dizini linguaforge_debug_dir filtresi aracılığıyla yapılandırın.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Etkinleştirildiğinde, ilk kez gelen ve dil çerezi veya URL\'de dil öneki olmayan ziyaretçiler, en yakın eşleşen dil sürümüne yönlendirilir. Yönlendirme, tarayıcının tercih ettiği dil aktif yönlendirici diller arasında değilse atlanır. Bir ziyaretçi, dil değiştirme aracını kullanarak bir dil seçtikten sonra, çerez öncelik kazanır ve tarayıcı başlığı tüm gelecekteki ziyaretlerde göz ardı edilir.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Tam sayfa çeviri için kullanılacak model seviyesi. Kalite, yukarıdaki Modeller tablosunda yapılandırılan modeli kullanır ve doğru, uzun biçimli çeviri için önerilir. Sadece hız veya maliyet öncelikliyse ve içerik kısa ise Hafif\'e geçin.','WP-CLI reference'=>'WP-CLI referansı','Write AI prompts and responses to disk for troubleshooting'=>'Sorun giderme için AI istemlerini ve yanıtlarını diske yazın','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Anahtarları sabitler veya ortam değişkenleri olarak da tanımlayabilirsiniz (örneğin wp-config.php\'de). Bu kaynaklar, veritabanı anahtarı depolanmadığında otomatik olarak yedek olarak kullanılır.','You do not have permission to manage these settings.'=>'Bu ayarları yönetme izniniz yok.','You do not have permission to read this post.'=>'Bu gönderiyi okuma izniniz yok.','{n} stale path(s)'=>'{n} eski yol(lar)','— Any source language —'=>'— Herhangi kaynak dili —','— Any target language —'=>'— Herhangi hedef dili —','— Any target —'=>'— Herhangi hedef —','— Any —'=>'— Herhangi —','— auto-detect —'=>'— otomatik tespit —','— select a language —'=>'— bir dil seçin —','— toggle in Settings → Behavior.'=>'— Ayarlar → Davranış\'taki anahtar.','← Back'=>'← Geri','↑ Detected from current post'=>'↑ Mevcut gönderiden algılandı','↺ Re-translate'=>'↺ Yeniden Çevir','↺ Refine'=>'↺ Geliştir','↺ Refresh'=>'↺ Yenile','↺ Refreshing…'=>'↺ Yenileme…','⚠ Borderline'=>'⚠ Sınırda','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ <strong>{lang}</strong> gönderisi bulunamadı. Tüm çevrilmiş gönderilerin Dil meta kutusunda <strong>{lang}</strong> olarak ayarlandığından emin olun.','⚠ No changes'=>'⚠ Değişiklik yok','⚠ No changes — re-scan?'=>'⚠ Değişiklik yok — tekrar tara?','✅ Fixed ({n})'=>'✅ Düzeltildi ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ <strong>{lang}</strong> için kırık bağlantı veya şablon uyuşmazlığı bulunmadı. <strong>{scanned}</strong> gönderi ve sayfa tarandı — tüm kontroller geçti. Şablon parçası bağlantıları (başlık, altbilgi, yan menü) burada dahil değildir — bunları ayrı kontrol etmek için Şablon Parçalarını Düzelt düğmesini kullanın.','✅ Template fixed'=>'✅ Şablon düzeltildi','✓ All parts created.'=>'✓ Tüm parçalar oluşturuldu.','✓ All templates created.'=>'✓ Tüm şablonlar oluşturuldu.','✓ All translated.'=>'✓ Tüm çeviriler yapıldı.','✓ Configured'=>'✓ Yapılandırıldı','✓ Connection OK'=>'✓ Bağlantı OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ İçerik oluşturuldu — gözden geçirmek, düzenlemek ve uygulamak için üsteki katmanı inceleyin.','✓ Done'=>'✓ Tamamlandı','✓ Enabled'=>'✓ Etkin','✓ Good length'=>'✓ İyi uzunluk','✓ In safe storage'=>'✓ Güvenli depolamada','✓ Language installed.'=>'✓ Dil yüklendi.','✓ Links fixed.'=>'✓ Bağlantılar düzeltildi.','✓ Nav refs fixed.'=>'✓ Navigasyon referansları düzeltildi.','✓ Parts fixed.'=>'✓ Parçalar düzeltildi.','✓ Pattern translated.'=>'✓ Desen çevrildi.','✓ Refined — review the updated draft above.'=>'✓ Düzenlendi — yukarıdaki güncellenmiş taslağı inceleyin.','✓ Translation saved'=>'✓ Çeviri kaydedildi','✗ Disabled'=>'✗ Devre Dışı','✗ Error:'=>'✗ Hata:','✗ Failed:'=>'✗ Başarısız:','✗ Not configured'=>'✗ Yapılandırılmadı','✗ Too long'=>'✗ Çok uzun','✗ Too short'=>'✗ Çok kısa','❌ Failed'=>'❌ Başarısız','📄 Wrong template'=>'📄 Yanlış şablon','📍 Stale path (page moved)'=>'📍 Eski yol (sayfa taşındı)']];
